      "sourceUrl": "https://raw.githubusercontent.com/coreyhaines31/marketingskills/88c79f6528a9347420e57ceb1fff9a60de651768/skills/customer-research/SKILL.md",
      "commit": "88c79f6528a9347420e57ceb1fff9a60de651768",
